// Initialize User Experience test configuration
const uxTestConfig = {
  testId: 'ux_test_' + Date.now(),
  startTime: new Date().toISOString(),
  testSuite: 'user_experience',
  playerPersonas: [
    {
      type: 'new_player',
      experience: 'beginner',
      goals: ['learn_game', 'create_character', 'complete_first_quest'],
      painPoints: ['complex_rules', 'overwhelming_options', 'unclear_objectives']
    },
    {
      type: 'experienced_player',
      experience: 'advanced',
      goals: ['optimize_character', 'master_advanced_features', 'lead_parties'],
      painPoints: ['limited_customization', 'repetitive_content', 'poor_ai_challenge']
    },
    {
      type: 'casual_player',
      experience: 'intermediate',
      goals: ['social_interaction', 'story_exploration', 'occasional_combat'],
      painPoints: ['time_commitment', 'complex_mechanics', 'social_pressure']
    },
    {
      type: 'power_gamer',
      experience: 'expert',
      goals: ['min_max_character', 'speed_run_content', 'competitive_advantage'],
      painPoints: ['balance_issues', 'exploit_fixes', 'progression_gates']
    }
  ],
  testScenarios: {
    newPlayerOnboarding: {
      steps: [
        'account_creation',
        'tutorial_completion',
        'character_creation',
        'first_session_join',
        'initial_combat_experience',
        'social_interaction_first'
      ],
      metrics: [
        'completion_rate',
        'time_to_completion',
        'error_rate',
        'satisfaction_score',
        'retention_indicators'
      ]
    },
    characterProgression: {
      progressionLevels: ['level_1_to_5', 'level_5_to_10', 'level_10_to_15', 'level_15_to_20'],
      progressionAspects: [
        'skill_advancement',
        'equipment_acquisition',
        'story_progression',
        'social_status',
        'mastery_development'
      ],
      satisfactionMetrics: [
        'meaningful_choices',
        'visible_progress',
        'achievement_adequacy',
        'challenge_appropriateness',
        'reward_satisfaction'
      ]
    },
    combatMechanics: {
      combatScenarios: [
        'single_enemy_encounter',
        'group_combat',
        'boss_battle',
        'pvp_combat',
        'environmental_hazards'
      ],
      mechanicsAspects: [
        'interface_usability',
        'action_clarity',
        'feedback_effectiveness',
        'tactical_depth',
        'flow_consistency'
      ],
      accuracyMetrics: [
        'rule_adherence',
        'calculation_correctness',
        'timing_precision',
        'effect_consistency',
        'balance_appropriateness'
      ]
    },
    socialInteraction: {
      interactionTypes: [
        'party_coordination',
        'npc_dialogue',
        'roleplaying immersion',
        'conflict_resolution',
        'community_engagement'
      ],
      qualityAspects: [
        'natural_conversation_flow',
        'meaningful_choices',
        'emotional_impact',
        'relationship_development',
        'social_rewards'
      ],
      qualityMetrics: [
        'engagement_depth',
        'conversation_satisfaction',
        'relationship_building',
        'immersion_level',
        'social_retention'
      ]
    },
    engagementMetrics: {
      trackingPeriods: ['session_based', 'daily', 'weekly', 'monthly'],
      engagementIndicators: [
        'session_duration',
        'return_frequency',
        'feature_adoption',
        'social_interaction',
        'content_consumption',
        'creation_activities'
      ],
      satisfactionMeasures: [
        'fun_factor',
        'challenge_satisfaction',
        'social_satisfaction',
        'progress_satisfaction',
        'overall_satisfaction'
      ]
    }
  },
  thresholds: {
    onboardingCompletion: 90,
    progressionSatisfaction: 80,
    combatAccuracy: 95,
    socialEngagement: 75,
    overallSatisfaction: 85
  }
};

$items[0].json.uxTestConfig = uxTestConfig;

return [{
  json: {
    ...uxTestConfig,
    status: 'initialized',
    currentTest: 'new_player_onboarding'
  }
}];

// Analyze User Experience test results and generate comprehensive report
const uxTestResults = {
  testId: $json.testId,
  testSuite: 'user_experience',
  startTime: $json.startTime,
  endTime: new Date().toISOString(),
  totalDuration: Date.now() - new Date($json.startTime).getTime(),
  tests: [
    {
      name: 'new_player_onboarding',
      status: $json.onboardingResults ? 'passed' : 'failed',
      completionRate: $json.onboardingCompletionRate || 0,
      averageTimeToComplete: $json.onboardingAvgTime || 0,
      errorRate: $json.onboardingErrorRate || 0,
      satisfactionScore: $json.onboardingSatisfaction || 0,
      retentionIndicators: $json.onboardingRetention || 0,
      threshold: $json.thresholds.onboardingCompletion,
      details: $json.onboardingDetails || {}
    },
    {
      name: 'character_progression_satisfaction',
      status: $json.progressionResults ? 'passed' : 'failed',
      satisfactionScore: $json.progressionSatisfaction || 0,
      meaningfulChoicesScore: $json.meaningfulChoicesScore || 0,
      visibleProgressScore: $json.visibleProgressScore || 0,
      achievementAdequacyScore: $json.achievementAdequacyScore || 0,
      challengeAppropriatenessScore: $json.challengeAppropriatenessScore || 0,
      threshold: $json.thresholds.progressionSatisfaction,
      details: $json.progressionDetails || {}
    },
    {
      name: 'combat_mechanics_accuracy',
      status: $json.combatResults ? 'passed' : 'failed',
      ruleAdherenceScore: $json.ruleAdherenceScore || 0,
      calculationCorrectnessScore: $json.calculationCorrectnessScore || 0,
      timingPrecisionScore: $json.timingPrecisionScore || 0,
      effectConsistencyScore: $json.effectConsistencyScore || 0,
      balanceAppropriatenessScore: $json.balanceAppropriatenessScore || 0,
      threshold: $json.thresholds.combatAccuracy,
      details: $json.combatDetails || {}
    },
    {
      name: 'social_interaction_quality',
      status: $json.socialResults ? 'passed' : 'failed',
      engagementDepthScore: $json.engagementDepthScore || 0,
      conversationSatisfactionScore: $json.conversationSatisfactionScore || 0,
      relationshipBuildingScore: $json.relationshipBuildingScore || 0,
      immersionLevelScore: $json.immersionLevelScore || 0,
      socialRetentionScore: $json.socialRetentionScore || 0,
      threshold: $json.thresholds.socialEngagement,
      details: $json.socialDetails || {}
    },
    {
      name: 'engagement_metrics',
      status: $json.engagementResults ? 'passed' : 'failed',
      overallSatisfactionScore: $json.overallSatisfactionScore || 0,
      sessionDurationScore: $json.sessionDurationScore || 0,
      returnFrequencyScore: $json.returnFrequencyScore || 0,
      featureAdoptionScore: $json.featureAdoptionScore || 0,
      contentConsumptionScore: $json.contentConsumptionScore || 0,
      threshold: $json.thresholds.overallSatisfaction,
      details: $json.engagementDetails || {}
    },
    {
      name: 'accessibility_testing',
      status: $json.accessibilityResults ? 'passed' : 'failed',
      complianceScore: $json.accessibilityComplianceScore || 0,
      usabilityScore: $json.accessibilityUsabilityScore || 0,
      taskCompletionRate: $json.accessibilityTaskCompletion || 0,
      errorFrequency: $json.accessibilityErrorFrequency || 0,
      details: $json.accessibilityDetails || {}
    },
    {
      name: 'responsiveness_testing',
      status: $json.responsivenessResults ? 'passed' : 'failed',
      layoutAdaptationScore: $json.layoutAdaptationScore || 0,
      touchTargetScore: $json.touchTargetScore || 0,
      readabilityScore: $json.readabilityScore || 0,
      navigationEaseScore: $json.navigationEaseScore || 0,
      deviceCompatibility: $json.deviceCompatibility || 0,
      details: $json.responsivenessDetails || {}
    },
    {
      name: 'load_performance',
      status: $json.loadPerformanceResults ? 'passed' : 'failed',
      averageLoadTime: $json.avgLoadTime || 0,
      timeToInteractive: $json.timeToInteractive || 0,
      frameRateScore: $json.frameRateScore || 0,
      memoryUsageScore: $json.memoryUsageScore || 0,
      networkUsageScore: $json.networkUsageScore || 0,
      details: $json.loadPerformanceDetails || {}
    }
  ],
  playerPersonas: $json.playerPersonas || [],
  overallMetrics: {
    averageSatisfaction: 0,
    totalUXScore: 0,
    accessibilityScore: 0,
    performanceScore: 0,
    usabilityScore: 0
  }
};

// Calculate UX summary
const passedTests = uxTestResults.tests.filter(t => t.status === 'passed').length;
const totalTests = uxTestResults.tests.length;
const successRate = (passedTests / totalTests * 100).toFixed(1);

// Calculate overall metrics
const satisfactionScores = uxTestResults.tests.map(t => t.satisfactionScore || t.overallSatisfactionScore || 0).filter(s => s > 0);
uxTestResults.overallMetrics.averageSatisfaction = 
  satisfactionScores.length > 0 ? satisfactionScores.reduce((sum, score) => sum + score, 0) / satisfactionScores.length : 0;

// Calculate component scores
const accessibilityTest = uxTestResults.tests.find(t => t.name === 'accessibility_testing');
const performanceTest = uxTestResults.tests.find(t => t.name === 'load_performance');
const usabilityTests = uxTestResults.tests.filter(t => 
  ['new_player_onboarding', 'combat_mechanics_accuracy', 'responsiveness_testing'].includes(t.name)
);

uxTestResults.overallMetrics.accessibilityScore = accessibilityTest ? (accessibilityTest.complianceScore + accessibilityTest.usabilityScore) / 2 : 0;
uxTestResults.overallMetrics.performanceScore = performanceTest ? 
  (performanceTest.averageLoadTime > 0 ? 100 - (performanceTest.averageLoadTime * 10) : 0) : 0;
uxTestResults.overallMetrics.usabilityScore = usabilityTests.length > 0 ? 
  usabilityTests.reduce((sum, test) => sum + (test.satisfactionScore || 0), 0) / usabilityTests.length : 0;

uxTestResults.overallMetrics.totalUXScore = (
  uxTestResults.overallMetrics.averageSatisfaction * 0.4 +
  uxTestResults.overallMetrics.accessibilityScore * 0.2 +
  uxTestResults.overallMetrics.performanceScore * 0.2 +
  uxTestResults.overallMetrics.usabilityScore * 0.2
);

// Determine UX quality rating
let uxQualityRating = 'excellent';
if (uxTestResults.overallMetrics.totalUXScore < 60) {
  uxQualityRating = 'poor';
} else if (uxTestResults.overallMetrics.totalUXScore < 75) {
  uxQualityRating = 'fair';
} else if (uxTestResults.overallMetrics.totalUXScore < 90) {
  uxQualityRating = 'good';
}

// Identify UX strengths and weaknesses
const strengths = [];
const weaknesses = [];
const criticalIssues = [];

uxTestResults.tests.forEach(test => {
  const score = test.satisfactionScore || test.overallSatisfactionScore || test.complianceScore || 0;
  const threshold = test.threshold || 80;

  if (score >= 90) {
    strengths.push(test.name.replace(/_/g, ' '));
  } else if (score < threshold) {
    if (score < 60) {
      criticalIssues.push(`${test.name.replace(/_/g, ' ')} (${score.toFixed(1)}%)`);
    } else {
      weaknesses.push(test.name.replace(/_/g, ' '));
    }
  }
});

// Player journey analysis
const journeyAnalysis = {
  onboardingExperience: uxTestResults.tests.find(t => t.name === 'new_player_onboarding'),
  progressionExperience: uxTestResults.tests.find(t => t.name === 'character_progression_satisfaction'),
  engagementRetention: uxTestResults.tests.find(t => t.name === 'engagement_metrics')
};

const summary = {
  totalTests,
  passedTests,
  failedTests: totalTests - passedTests,
  successRate: parseFloat(successRate),
  overallStatus: criticalIssues.length > 0 ? 'failed' : successRate >= 85 ? 'passed' : 'warning',
  uxQualityRating,
  overallMetrics: uxTestResults.overallMetrics,
  strengths,
  weaknesses,
  criticalIssues,
  journeyAnalysis
};

return [{
  json: {
    testSuite: 'user_experience',
    ...uxTestResults,
    summary,
    status: summary.overallStatus,
    timestamp: new Date().toISOString()
  }
}];

// Generate UX improvement recommendations and player insights
const recommendations = [];
const playerInsights = [];
const painPoints = [];

// Analyze each UX test for specific recommendations
$json.tests.forEach(test => {
  const score = test.satisfactionScore || test.overallSatisfactionScore || test.complianceScore || 0;
  const threshold = test.threshold || 80;

  if (test.name === 'new_player_onboarding' && score < threshold) {
    recommendations.push({
      category: 'onboarding',
      priority: 'high',
      issue: 'New player onboarding completion rate below target',
      suggestion: 'Simplify tutorial flow, provide clearer guidance, and reduce cognitive overload'
    });
    painPoints.push('Confusing initial experience for new players');
  }

  if (test.name === 'character_progression_satisfaction' && score < threshold) {
    recommendations.push({
      category: 'progression',
      priority: 'high',
      issue: 'Character progression satisfaction below expectations',
      suggestion: 'Enhance meaningful choices, improve visible progress indicators, and balance challenge scaling'
    });
    painPoints.push('Lack of meaningful character advancement');
  }

  if (test.name === 'combat_mechanics_accuracy' && score < threshold) {
    recommendations.push({
      category: 'combat',
      priority: 'critical',
      issue: 'Combat mechanics accuracy issues detected',
      suggestion: 'Review rule implementation, improve calculation accuracy, and enhance feedback systems'
    });
    painPoints.push('Combat system reliability problems');
  }

  if (test.name === 'social_interaction_quality' && score < threshold) {
    recommendations.push({
      category: 'social',
      priority: 'medium',
      issue: 'Social interaction quality needs improvement',
      suggestion: 'Enhance NPC dialogue variety, improve relationship mechanics, and deepen social consequences'
    });
    painPoints.push('Limited social engagement opportunities');
  }

  if (test.name === 'engagement_metrics' && score < threshold) {
    recommendations.push({
      category: 'engagement',
      priority: 'high',
      issue: 'Player engagement below target levels',
      suggestion: 'Analyze player behavior patterns, introduce compelling content, and improve retention mechanisms'
    });
    painPoints.push 'Difficulty maintaining player interest';
  }
});

// Generate player insights based on persona analysis
$json.playerPersonas.forEach(persona => {
  const relevantTests = $json.tests.filter(test => {
    // Map tests to persona concerns
    if (persona.type === 'new_player') {
      return ['new_player_onboarding', 'accessibility_testing', 'load_performance'].includes(test.name);
    } else if (persona.type === 'experienced_player') {
      return ['character_progression_satisfaction', 'combat_mechanics_accuracy', 'social_interaction_quality'].includes(test.name);
    } else if (persona.type === 'casual_player') {
      return ['social_interaction_quality', 'engagement_metrics', 'accessibility_testing'].includes(test.name);
    } else if (persona.type === 'power_gamer') {
      return ['combat_mechanics_accuracy', 'character_progression_satisfaction', 'load_performance'].includes(test.name);
    }
    return false;
  });

  const avgScore = relevantTests.reduce((sum, test) => {
    const score = test.satisfactionScore || test.overallSatisfactionScore || test.complianceScore || 0;
    return sum + score;
  }, 0) / relevantTests.length;

  playerInsights.push({
    persona: persona.type,
    experience: persona.experience,
    satisfactionScore: avgScore,
    primaryConcerns: persona.painPoints,
    keyRecommendations: relevantTests.filter(t => {
      const score = t.satisfactionScore || t.overallSatisfactionScore || t.complianceScore || 0;
      return score < (t.threshold || 80);
    }).map(t => t.name.replace(/_/g, ' '))
  });
});

// Generate overall player journey insights
const journeyBottlenecks = [];
if ($json.summary.journeyAnalysis.onboardingExperience && 
    $json.summary.journeyAnalysis.onboardingExperience.completionRate < 90) {
  journeyBottlenecks.push('Onboarding drop-off - players struggle to get started');
}

if ($json.summary.journeyAnalysis.progressionExperience && 
    $json.summary.journeyAnalysis.progressionExperience.satisfactionScore < 80) {
  journeyBottlenecks.push('Progression frustration - players feel stuck or under-rewarded');
}

if ($json.summary.journeyAnalysis.engagementRetention && 
    $json.summary.journeyAnalysis.engagementRetention.returnFrequencyScore < 70) {
  journeyBottlenecks.push('Retention issues - players not returning regularly');
}

// UX quality improvement roadmap
const improvementRoadmap = {
  immediate_fixes: recommendations.filter(r => r.priority === 'critical'),
  short_term_improvements: recommendations.filter(r => r.priority === 'high'),
  long_term_enhancements: recommendations.filter(r => r.priority === 'medium')
};

return [{
  json: {
    testId: $json.testId,
    recommendations,
    playerInsights,
    painPoints,
    journeyBottlenecks,
    improvementRoadmap,
    summary: {
      totalRecommendations: recommendations.length,
      criticalFixes: recommendations.filter(r => r.priority === 'critical').length,
      highPriorityIssues: recommendations.filter(r => r.priority === 'high').length,
      mediumPriorityIssues: recommendations.filter(r => r.priority === 'medium').length,
      identifiedPainPoints: painPoints.length,
      journeyBottlenecks: journeyBottlenecks.length
    },
    timestamp: new Date().toISOString()
  }
}];
